<?php
namespace Tests\Feature;
use App\Models\{SubscriptionPlan,User};use App\Services\Team\TeamSeatUsage;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Inertia\Testing\AssertableInertia as Assert;use Tests\TestCase;
class AddTeamMemberVisibilityTest extends TestCase{use RefreshDatabase;private function owner():User{return User::create(['name'=>'Owner','email'=>'add-team-owner@test.local','password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer','plan'=>'standard']);}
public function test_reached_limit_keeps_capability_and_reports_actual_usage():void{$o=$this->owner();SubscriptionPlan::where('code','standard')->update(['team_seat_limit'=>1]);$o->teamInvitations()->create(['uuid'=>fake()->uuid(),'name'=>'Pending','email'=>'pending@test.local','role'=>'viewer','token_hash'=>hash('sha256','x'),'status'=>'pending','invited_by'=>$o->id,'expires_at'=>now()->addDay()]);$this->actingAs($o)->get(route('settings.team-login'))->assertInertia(fn(Assert$p)=>$p->where('canInviteTeamMembers',true)->where('seatUsage.used',1)->where('seatUsage.limit',1)->where('seatUsage.reached',true));$source=file_get_contents(resource_path('js/Pages/Settings/TeamLogin.vue'));$this->assertStringContainsString(':disabled="seatUsage.reached"',$source);$this->assertStringContainsString('team-member limit has been reached',$source);}
public function test_missing_limit_is_explicitly_unlimited_not_zero():void{$o=$this->owner();SubscriptionPlan::where('code','standard')->update(['team_seat_limit'=>null]);$summary=app(TeamSeatUsage::class)->summary($o);$this->assertNull($summary['limit']);$this->assertTrue($summary['unlimited']);$this->assertFalse($summary['reached']);}
public function test_owner_role_and_unauthorized_submission_are_rejected():void{$o=$this->owner();$this->actingAs($o)->post(route('settings.team-login.invitations.store'),['name'=>'Wrong Role','email'=>'wrong-role@test.local','role'=>'owner'])->assertSessionHasErrors('role');$participant=User::create(['name'=>'Participant','email'=>'participant-add-team@test.local','password'=>Hash::make('x'),'status'=>'active','account_type'=>'user']);$this->actingAs($participant)->post(route('settings.team-login.invitations.store'),['name'=>'No Access','email'=>'blocked@test.local','role'=>'viewer'])->assertForbidden();}}
